delete from public.property_photos where id='30000000-0000-4000-8000-000000000001';
select is((select completeness_score from public.listings where id='20000000-0000-4000-8000-000000000001'), 0.6::numeric, 'removing one of two photos preserves contribution');
select ok(((select ctid::text from public.listings where id='20000000-0000-4000-8000-000000000001')=(select row_tid from unchanged)), 'unchanged score avoids updated_at/row churn');
delete from public.property_photos where property_id='10000000-0000-4000-8000-000000000001';
select is((select completeness_score from public.listings where id='20000000-0000-4000-8000-000000000001'), 0.4::numeric, 'last photo removal subtracts twenty');
insert into public.property_amenities values('10000000-0000-4000-8000-000000000001',1);
