insert into public.property_private_locations(property_id,address_line_1) values('10000000-0000-4000-8000-000000000001','Test fixture only');
select is((select completeness_score from public.listings where id='20000000-0000-4000-8000-000000000001'), 0.55::numeric, 'private location existence adds fifteen');
