delete from public.property_private_locations where property_id='10000000-0000-4000-8000-000000000001';
select is((select completeness_score from public.listings where id='20000000-0000-4000-8000-000000000001'), 0.4::numeric, 'private location deletion subtracts fifteen');
update public.properties set floor_area_sqm=0 where id='10000000-0000-4000-8000-000000000001';
select is((select completeness_score from public.listings where id='20000000-0000-4000-8000-000000000001'), 0.5::numeric, 'non-null floor area adds ten including server-accepted zero');
update public.properties set max_occupants=2 where id='10000000-0000-4000-8000-000000000001';
select is((select completeness_score from public.listings where id='20000000-0000-4000-8000-000000000001'), 0.55::numeric, 'non-null occupants add five');
