select ok(((select ctid::text from public.listings where id='20000000-0000-4000-8000-000000000001')=(select row_tid from unchanged)), 'non-null area value change does not write unchanged score');
update public.properties set note='unrelated' where id='10000000-0000-4000-8000-000000000001';
