select is((select completeness_score from public.listings where id='20000000-0000-4000-8000-000000000002'), 0.65::numeric, 'private row reassignment refreshes new property');
update public.properties set floor_area_sqm=30,max_occupants=2 where id='10000000-0000-4000-8000-000000000001';
insert into public.property_photos(id,property_id) values('30000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000001');
insert into public.property_amenities values('10000000-0000-4000-8000-000000000001',4);
insert into public.property_private_locations(property_id) values('10000000-0000-4000-8000-000000000001');
select is((select completeness_score from public.listings where id='20000000-0000-4000-8000-000000000001'), 1::numeric, 'full persisted property/listing is 100 percent');
insert into public.listings(id,property_id,landlord_id,title,description,asking_rent_monthly,available_from,status) values('20000000-0000-4000-8000-000000000010','10000000-0000-4000-8000-000000000001','90000000-0000-4000-8000-000000000001','History',repeat('x',30),100,current_date,'paused');
insert into public.listings(id,property_id,landlord_id,title,description,asking_rent_monthly,available_from,status) values('20000000-0000-4000-8000-000000000011','10000000-0000-4000-8000-000000000001','90000000-0000-4000-8000-000000000001','History',repeat('x',30),100,current_date,'rented');
insert into public.listings(id,property_id,landlord_id,title,description,asking_rent_monthly,available_from,status) values('20000000-0000-4000-8000-000000000012','10000000-0000-4000-8000-000000000001','90000000-0000-4000-8000-000000000001','History',repeat('x',30),100,current_date,'archived');
insert into public.listings(id,property_id,landlord_id,title,description,asking_rent_monthly,available_from,status) values('20000000-0000-4000-8000-000000000013','10000000-0000-4000-8000-000000000001','90000000-0000-4000-8000-000000000001','History',repeat('x',30),100,current_date,'removed');
