select is((select completeness_score from public.listings where id='20000000-0000-4000-8000-000000000001'), 1::numeric, 'non-completeness metadata edit remains allowed on active listing');
delete from public.property_amenities where property_id='10000000-0000-4000-8000-000000000001';
select is((select completeness_score from public.listings where id='20000000-0000-4000-8000-000000000001'), 0.9::numeric, 'active listing may lose a noncritical ten percent');
