select is((select completeness_score from public.listings where id='20000000-0000-4000-8000-000000000001'), 0.8::numeric, 'exactly eighty percent remains active');
select ok(((select status='active' from public.listings where id='20000000-0000-4000-8000-000000000001')), 'eighty percent preserves active status');
select throws_ok($test$delete from public.property_photos where property_id='10000000-0000-4000-8000-000000000001'$test$,'P0001','Listing must reach at least 80% completeness before publishing','active listing rejects critical photo loss transactionally');
select is((select completeness_score from public.listings where id='20000000-0000-4000-8000-000000000001'), 0.8::numeric, 'rejected photo mutation preserves stored active score');
select throws_ok($test$delete from public.property_private_locations where property_id='10000000-0000-4000-8000-000000000001'$test$,'P0001','Listing must reach at least 80% completeness before publishing','active listing rejects critical private location loss transactionally');
select is((select completeness_score from public.listings where id='20000000-0000-4000-8000-000000000001'), 0.8::numeric, 'rejected private location mutation preserves stored active score');
select throws_ok($test$update public.properties set max_occupants=null where id='10000000-0000-4000-8000-000000000001'$test$,'P0001','Listing must reach at least 80% completeness before publishing','active listing rejects critical occupants loss transactionally');
select is((select completeness_score from public.listings where id='20000000-0000-4000-8000-000000000001'), 0.8::numeric, 'rejected occupants mutation preserves stored active score');
select ok((exists(select 1 from public.property_photos where property_id='10000000-0000-4000-8000-000000000001')), 'critical photo remains after rejected delete');
select ok((exists(select 1 from public.property_private_locations where property_id='10000000-0000-4000-8000-000000000001')), 'critical private row remains after rejected delete');
select ok(((select published_at from public.listings where id='20000000-0000-4000-8000-000000000001')=(select published_at from active_time)), 'refresh preserves existing published_at');
