update public.properties set floor_area_sqm=null,max_occupants=null where id='10000000-0000-4000-8000-000000000001';
select throws_ok($test$delete from public.property_amenities where property_id='10000000-0000-4000-8000-000000000001'$test$,'P0001','Listing must reach at least 80% completeness before publishing','critical final amenity removal rejected');
select is((select completeness_score from public.listings where id='20000000-0000-4000-8000-000000000001'),.80::numeric,'amenity removal rolls back score and row');
update public.properties set floor_area_sqm=30 where id='10000000-0000-4000-8000-000000000001';
