select is((select completeness_score from public.listings where id='20000000-0000-4000-8000-000000000001'),.80::numeric,'floor removal rolls back score and property');
select throws_ok($test$insert into public.listings(id,property_id,landlord_id,title,description,asking_rent_monthly,status) values('20000000-0000-4000-8000-000000000088','10000000-0000-4000-8000-000000000001','90000000-0000-4000-8000-000000000001','Bad',repeat('x',30),100,'active')$test$,'P0001','Create the listing as a draft before publishing','direct active insert remains forbidden');
select throws_ok($test$update public.listings set landlord_id='90000000-0000-4000-8000-000000000002' where id='20000000-0000-4000-8000-000000000001'$test$,'P0001','Listing landlord must own the referenced property','listing ownership still validated');
select ok((not has_schema_privilege('anon','rentlease_completeness','USAGE')), 'anon lacks internal schema usage');
select ok((not has_function_privilege('anon','rentlease_completeness.calculate_listing_completeness(uuid,text,text,numeric,date)','EXECUTE')), 'anon cannot invoke calculate_listing_completeness');
select ok((not has_function_privilege('anon','rentlease_completeness.refresh_listing_completeness_for_property(uuid)','EXECUTE')), 'anon cannot invoke refresh_listing_completeness_for_property');
select ok((not has_function_privilege('anon','rentlease_completeness.lock_related_property()','EXECUTE')), 'anon cannot invoke lock_related_property');
select ok((not has_function_privilege('anon','rentlease_completeness.refresh_related_property()','EXECUTE')), 'anon cannot invoke refresh_related_property');
select ok((not has_schema_privilege('authenticated','rentlease_completeness','USAGE')), 'authenticated lacks internal schema usage');
select ok((not has_function_privilege('authenticated','rentlease_completeness.calculate_listing_completeness(uuid,text,text,numeric,date)','EXECUTE')), 'authenticated cannot invoke calculate_listing_completeness');
select ok((not has_function_privilege('authenticated','rentlease_completeness.refresh_listing_completeness_for_property(uuid)','EXECUTE')), 'authenticated cannot invoke refresh_listing_completeness_for_property');
select ok((not has_function_privilege('authenticated','rentlease_completeness.lock_related_property()','EXECUTE')), 'authenticated cannot invoke lock_related_property');
select ok((not has_function_privilege('authenticated','rentlease_completeness.refresh_related_property()','EXECUTE')), 'authenticated cannot invoke refresh_related_property');
select ok((not has_table_privilege('authenticated','public.listings','UPDATE')), 'no authenticated listing UPDATE grant added');
select set_config('request.jwt.claim.sub','90000000-0000-4000-8000-000000000001',true);
set local role authenticated;
insert into public.property_photos(id,property_id) values('30000000-0000-4000-8000-000000000008','10000000-0000-4000-8000-000000000002');
reset role;
select is((select completeness_score from public.listings where id='20000000-0000-4000-8000-000000000002'), 0.65::numeric, 'authorized related writer succeeds without listing UPDATE privilege');
select set_config('request.jwt.claim.sub','90000000-0000-4000-8000-000000000002',true);
set local role authenticated;
select throws_ok($test$insert into public.property_photos(id,property_id) values('30000000-0000-4000-8000-000000000009','10000000-0000-4000-8000-000000000001')$test$,'42501',null,'unrelated authenticated writer still denied by RLS');
reset role;
delete from public.properties where id='10000000-0000-4000-8000-000000000001';
select is((select count(*) from public.listings where property_id='10000000-0000-4000-8000-000000000001'), 0::bigint, 'parent cascade remains valid without orphan completeness refresh');
select * from finish();
rollback;
